  'pr.settings': ['Configuração', 'Settings', 'Configuración'],
  'pr.settingsDesc': [
    'Ligada, a tag pede os floors do site e manda o do bloco para o GAM. O motor revê cada regra a cada hora.',
    'When on, the tag asks for the site floors and sends each block floor to GAM. The engine reviews every rule each hour.',
    'Encendida, la tag pide los floors del sitio y envía el del bloque a GAM. El motor revisa cada regla cada hora.',
  ],
  'pr.controlLabel': ['Grupo de controle: {percent}% dos visitantes', 'Control group: {percent}% of visitors', 'Grupo de control: {percent}% de los visitantes'],
  'pr.controlHint': [
    'Esses visitantes não recebem floor. A diferença de receita entre os dois grupos é o ganho da regra. Vai de 0% a {max}%.',
    'These visitors get no floor. The revenue difference between both groups is the rule gain. From 0% to {max}%.',
    'Estos visitantes no reciben floor. La diferencia de ingresos entre los dos grupos es la ganancia de la regla. De 0% a {max}%.',
  ],
  'pr.tagDelay': ['Muda na tag em até 1 hora.', 'Reaches the tag within 1 hour.', 'Llega a la tag en hasta 1 hora.'],
  'pr.ruleOnSite': ['Regra no site', 'Rule on the site', 'Regla en el sitio'],
  'pr.activeHint.on': ['Ligada: os visitantes fora do controle recebem floor.', 'On: visitors outside the control group get a floor.', 'Encendida: los visitantes fuera del control reciben floor.'],
  'pr.activeHint.off': ['Desligada: nenhum visitante recebe floor.', 'Off: no visitor gets a floor.', 'Apagada: ningún visitante recibe floor.'],
  'pr.blocksCount': ['{automatic} com a Automática · {cascade} com a Cascata', '{automatic} on Automatic · {cascade} on Cascade', '{automatic} con la Automática · {cascade} con la Cascada'],
  'pr.blocksHint': [
    'Cada bloco roda um modelo só, Automática ou Cascata. Recomendamos a Automática no conteúdo e a Cascata na âncora, no intersticial, no fixo e no reward. Na Cascata, se ninguém compra, a tag dá um novo lance com floor menor, até 4 tentativas, a última sem floor. No conteúdo, no intersticial e no reward, as tentativas começam depois do teste em página real. O offerwall é do Google e fica sem regra.',
    'Each block runs a single model, Automatic or Cascade. We recommend Automatic on content and Cascade on anchor, interstitial, fixed and reward. On Cascade, if nobody buys, the tag bids again with a lower floor, up to 4 tries, the last one with no floor. On content, interstitial and reward, the tries start after the test on a real page. The offerwall belongs to Google and has no rule.',
    'Cada bloque usa un solo modelo, Automática o Cascada. Recomendamos la Automática en el contenido y la Cascada en el ancla, el intersticial, el fijo y el reward. En la Cascada, si nadie compra, la tag hace una nueva puja con un floor menor, hasta 4 intentos, el último sin floor. En el contenido, el intersticial y el reward, los intentos empiezan después de la prueba en una página real. El offerwall es de Google y queda sin regla.',
  ],
  'pr.unsaved': ['Alterações não salvas. Mudam na tag em até 1 hora.', 'Unsaved changes. They reach the tag within 1 hour.', 'Cambios sin guardar. Llegan a la tag en hasta 1 hora.'],
