  'pr.cascade.desc': [
    'Uma regra por bloco e país, para o site inteiro. Se ninguém compra, a tag dá um novo lance no mesmo bloco com o próximo floor da escada, até 4 tentativas em no máximo 3 segundos. A 4ª vai sem floor. No conteúdo, no intersticial e no reward, as tentativas começam depois do teste em página real.',
    'One rule per block and country, for the whole site. If nobody buys, the tag bids again on the same block with the next floor of the ladder, up to 4 tries in at most 3 seconds. The 4th goes with no floor. On content, interstitial and reward, the tries start after the test on a real page.',
    'Una regla por bloque y país, para todo el sitio. Si nadie compra, la tag hace una nueva puja en el mismo bloque con el siguiente floor de la escalera, hasta 4 intentos en máximo 3 segundos. El 4.º va sin floor. En el contenido, el intersticial y el reward, los intentos empiezan después de la prueba en una página real.',
  ],
