  'at.guideDesc': ['Cada tag tem a sua linha com a chave dela. Siga os passos na ordem.', 'Each tag has its own line with its key. Follow the steps in order.', 'Cada tag tiene su línea con su clave. Sigue los pasos en orden.'],
  'at.guideStep1': ['Crie a tag do site em "Nova tag" e monte os blocos e as integrações.', 'Create the site tag in "New tag" and set up the blocks and integrations.', 'Crea la tag del sitio en "Nueva tag" y arma los bloques y las integraciones.'],
