  'at.guideStep3': ['Clique em "Instalar" na linha da tag, nesta tabela, e copie a linha com a chave dela.', 'Click "Install" on the tag row in this table and copy the line with its key.', 'Haz clic en "Instalar" en la fila de la tag, en esta tabla, y copia la línea con su clave.'],
  'at.guideStep4': ['Cole a linha no <head> das páginas do site que devem usar a tag.', 'Paste the line in the <head> of the site pages that should use the tag.', 'Pega la línea en el <head> de las páginas del sitio que deben usar la tag.'],
  'at.guideStep5': ['Em poucos minutos a situação muda para "No ar" e as Métricas começam a mostrar a tag.', 'Within a few minutes the status changes to "Live" and Metrics starts showing the tag.', 'En pocos minutos la situación cambia a "En línea" y Métricas empieza a mostrar la tag.'],
  'at.guideLineHint': ['Assim fica a linha. A chave de cada tag aparece em "Instalar".', 'This is what the line looks like. Each tag key is shown in "Install".', 'Así queda la línea. La clave de cada tag aparece en "Instalar".'],
