  'at.installGenius': ['Tire a tag antiga do Genius (g-tag.min.js) para os anúncios não aparecerem duas vezes.', 'Remove the old Genius tag (g-tag.min.js) so ads do not show twice.', 'Quita la tag antigua de Genius (g-tag.min.js) para que los anuncios no aparezcan dos veces.'],
  'at.installOne': ['Uma página deve ter só uma tag. Com duas, a primeira que carregar vale e a outra fica parada.', 'A page should have only one tag. With two, the first one to load wins and the other stays idle.', 'Una página debe tener solo una tag. Con dos, vale la primera que cargue y la otra queda parada.'],
