  'gads.objects.foot': ['Receita, lucro e ROI só aparecem nas contas com site e UTMs. A receita vem das UTMs utm_campaign, utm_content, utm_term e utm_keyword com os ids do Google Ads. Performance Max e Vídeo entram nos números, mas são criados no Google Ads.', 'Revenue, profit and ROI only show for accounts with a site and UTMs. Revenue comes from the utm_campaign, utm_content, utm_term and utm_keyword UTMs carrying the Google Ads ids. Performance Max and Video count in the numbers but are created in Google Ads.', 'Ingresos, ganancia y ROI solo aparecen en las cuentas con sitio y UTM. Los ingresos vienen de las UTM utm_campaign, utm_content, utm_term y utm_keyword con los ids de Google Ads. Performance Max y Video entran en los números, pero se crean en Google Ads.'],
